CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, mobile VARCHAR(18) NOT NULL, password_hash VARCHAR(72) NOT NULL, role ENUM('SEEKER','EMPLOYER','ADMIN') NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(role,created));
CREATE TABLE IF NOT EXISTS job_seeker_profiles (user_id BIGINT PRIMARY KEY,location VARCHAR(180) NOT NULL,qualification VARCHAR(160) NOT NULL, details JSON NOT NULL,resume MEDIUMBLOB,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS employer_profiles (user_id BIGINT PRIMARY KEY,company VARCHAR(180) NOT NULL,details JSON NOT NULL,logo MEDIUMBLOB,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS skills (id BIGINT PRIMARY KEY AUTO_INCREMENT,norm VARCHAR(64) NOT NULL UNIQUE, label VARCHAR(64) NOT NULL);
CREATE TABLE IF NOT EXISTS candidate_skills (candidate_id BIGINT NOT NULL,skill_id BIGINT NOT NULL,PRIMARY KEY(candidate_id,skill_id),FOREIGN KEY(candidate_id) REFERENCES job_seeker_profiles(user_id),FOREIGN KEY(skill_id) REFERENCES skills(id));
CREATE TABLE IF NOT EXISTS jobs (id BIGINT PRIMARY KEY AUTO_INCREMENT,employer_id BIGINT NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,responsibilities TEXT NOT NULL,qualification VARCHAR(160) NOT NULL,experience VARCHAR(180) NOT NULL,location VARCHAR(180) NOT NULL,category VARCHAR(80) NOT NULL,type VARCHAR(60) NOT NULL,salary VARCHAR(150) NOT NULL DEFAULT '',deadline DATE NOT NULL,publication ENUM('Draft','Published','Closed') NOT NULL,sample BOOLEAN NOT NULL DEFAULT FALSE,posted TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(employer_id) REFERENCES employer_profiles(user_id),INDEX(publication,deadline),INDEX(employer_id),INDEX(category));
CREATE TABLE IF NOT EXISTS job_required_skills(job_id BIGINT NOT NULL,skill_id BIGINT NOT NULL,PRIMARY KEY(job_id,skill_id),FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(id));
CREATE TABLE IF NOT EXISTS applications (id BIGINT PRIMARY KEY AUTO_INCREMENT,candidate_id BIGINT NOT NULL,job_id BIGINT NOT NULL,status ENUM('Pending','Shortlisted','Selected','Rejected') NOT NULL DEFAULT 'Pending',applied TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(candidate_id,job_id),FOREIGN KEY(candidate_id) REFERENCES job_seeker_profiles(user_id),FOREIGN KEY(job_id) REFERENCES jobs(id),INDEX(job_id,status));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,message VARCHAR(600) NOT NULL,seen BOOLEAN DEFAULT FALSE,created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id,created));
CREATE TABLE IF NOT EXISTS saved_jobs(user_id BIGINT NOT NULL,job_id BIGINT NOT NULL,PRIMARY KEY(user_id,job_id),FOREIGN KEY(user_id) REFERENCES job_seeker_profiles(user_id),FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS contact_messages(id BIGINT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(180) NOT NULL,message TEXT NOT NULL,created TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
